        if not VarExists('Colors[0]') then begin
            clRed    := 'C80000';
            clBlue   := '0000C8';
            clGreen  := '009600';
            clYellow := 'FFFF00';

            Colors[0] := clRed;
            Colors[1] := clBlue;
            Colors[2] := clGreen;
            Colors[3] := clYellow;
        end;

